('a26051d5-dce8-4b5d-ba1f-28e9f687983d', '', 10, 0, 0, '[]', 'a:2:{s:13:\"allowFailures\";b:1;s:7:\"finally\";a:1:{i:0;O:47:\"Laravel\\SerializableClosure\\SerializableClosure\":1:{s:12:\"serializable\";O:46:\"Laravel\\SerializableClosure\\Serializers\\Signed\":2:{s:12:\"serializable\";s:4007:\"O:46:\"Laravel\\SerializableClosure\\Serializers\\Native\":5:{s:3:\"use\";a:5:{s:9:\"authGuard\";s:3:\"web\";s:9:\"columnMap\";a:7:{s:10:\"department\";s:10:\"department\";s:5:\"batch\";s:5:\"batch\";s:7:\"section\";s:7:\"section\";s:10:\"student_id\";s:10:\"student_id\";s:4:\"name\";s:4:\"name\";s:5:\"email\";s:5:\"email\";s:5:\"phone\";s:5:\"phone\";}s:6:\"import\";O:45:\"Illuminate\\Contracts\\Database\\ModelIdentifier\":5:{s:5:\"class\";s:38:\"Filament\\Actions\\Imports\\Models\\Import\";s:2:\"id\";i:1;s:9:\"relations\";a:0:{}s:10:\"connection\";s:5:\"mysql\";s:15:\"collectionClass\";N;}s:13:\"jobConnection\";N;s:7:\"options\";a:0:{}}s:8:\"function\";s:3292:\"function () use ($authGuard, $columnMap, $import, $jobConnection, $options): void {\n                    $import->touch(\'completed_at\');\n\n                    event(new \\Filament\\Actions\\Imports\\Events\\ImportCompleted($import, $columnMap, $options));\n\n                    if (! $import->user instanceof \\Illuminate\\Contracts\\Auth\\Authenticatable) { /** @phpstan-ignore instanceof.alwaysTrue */\n                        return;\n                    }\n\n                    $import->columnMap($columnMap);\n                    $import->options($options);\n\n                    $failedRowsCount = $import->getFailedRowsCount();\n\n                    $isSynchronous = ($jobConnection === \'sync\') || (blank($jobConnection) && (config(\'queue.default\') === \'sync\'));\n\n                    $notification = \\Filament\\Notifications\\Notification::make()\n                        ->title($import->importer::getCompletedNotificationTitle($import))\n                        ->body($import->importer::getCompletedNotific